// POST /api/speak
// Turns a live answer into speech with ElevenLabs' low-latency model, in Quill's voice or the
// machine's own voice. Pre-written story lines don't come here: they are pre-generated by
// `npm run voice` into public/audio. The ElevenLabs key stays on the server.
//
// Body:    { text: string, speaker: 'quill' | 'machine', machineId?: string }
// Returns: audio/mpeg, or an error status so the app falls back to the browser's voice.
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

let bodies: Map<string, string> | null = null
function bodyOf(machineId: string): string | undefined {
  if (!bodies) {
    const raw = readFileSync(join(process.cwd(), 'src', 'data', 'machines.json'), 'utf8')
    const data = JSON.parse(raw) as { machines: { id: string; body: string }[] }
    bodies = new Map(data.machines.map((m) => [m.id, m.body]))
  }
  return bodies.get(machineId)
}

/**
 * Voice IDs come from environment variables (same rules as scripts/gen-voice.mjs):
 * Quill → ELEVENLABS_VOICE_QUILL. A machine → its own ELEVENLABS_VOICE_<ID> (e.g. ELEVENLABS_VOICE_SOJOURNER),
 * else ELEVENLABS_VOICE_MOON / ELEVENLABS_VOICE_MARS by world, else ELEVENLABS_VOICE_MACHINE.
 */
function voiceFor(speaker: string, machineId: string | undefined): string | undefined {
  const env = process.env
  if (speaker === 'quill') return env.ELEVENLABS_VOICE_QUILL
  if (machineId && bodyOf(machineId)) {
    const own = env[`ELEVENLABS_VOICE_${machineId.toUpperCase().replace(/[^A-Z0-9]/g, '_')}`]
    if (own) return own
    const world = bodyOf(machineId)
    if (world === 'moon' && env.ELEVENLABS_VOICE_MOON) return env.ELEVENLABS_VOICE_MOON
    if (world === 'mars' && env.ELEVENLABS_VOICE_MARS) return env.ELEVENLABS_VOICE_MARS
  }
  return env.ELEVENLABS_VOICE_MACHINE || env.ELEVENLABS_VOICE_MOON || env.ELEVENLABS_VOICE_MARS
}

// Best-effort limit per visitor (each server instance keeps its own count).
const hits = new Map<string, { n: number; reset: number }>()
function allowed(ip: string, limit: number): boolean {
  const now = Date.now()
  const h = hits.get(ip)
  if (!h || now > h.reset) {
    hits.set(ip, { n: 1, reset: now + 60_000 })
    return true
  }
  h.n += 1
  return h.n <= limit
}

export async function POST(request: Request): Promise<Response> {
  const key = process.env.ELEVENLABS_API_KEY
  if (!key || process.env.LIVE_VOICE_ENABLED === 'false') return new Response(null, { status: 503 })

  const ip = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'local'
  if (!allowed(ip, Number(process.env.SPEAK_PER_MINUTE ?? 30))) return new Response(null, { status: 429 })

  let body: { text?: unknown; speaker?: unknown; machineId?: unknown }
  try {
    body = (await request.json()) as typeof body
  } catch {
    return new Response(null, { status: 400 })
  }
  const text = typeof body.text === 'string' ? body.text.trim().slice(0, 600) : ''
  const speaker = body.speaker === 'quill' ? 'quill' : 'machine'
  const machineId = typeof body.machineId === 'string' ? body.machineId : undefined
  const voiceId = voiceFor(speaker, machineId)
  if (!text || !voiceId) return new Response(null, { status: 400 })

  const ctrl = new AbortController()
  const timer = setTimeout(() => ctrl.abort(), Number(process.env.SPEAK_TIMEOUT_MS ?? 8000))
  try {
    const res = await fetch(
      `https://api.elevenlabs.io/v1/text-to-speech/${encodeURIComponent(voiceId)}/stream?output_format=mp3_44100_128`,
      {
        method: 'POST',
        headers: { 'xi-api-key': key, 'content-type': 'application/json', accept: 'audio/mpeg' },
        body: JSON.stringify({ text, model_id: process.env.ELEVENLABS_LIVE_MODEL || 'eleven_flash_v2_5' }),
        signal: ctrl.signal,
      },
    )
    if (!res.ok) {
      console.error('[api/speak] ElevenLabs', res.status, (await res.text()).slice(0, 200))
      return new Response(null, { status: 502 })
    }
    const audio = await res.arrayBuffer()
    return new Response(audio, { headers: { 'content-type': 'audio/mpeg', 'cache-control': 'no-store' } })
  } catch (err) {
    console.error('[api/speak]', err instanceof Error ? err.message : 'failed')
    return new Response(null, { status: 504 })
  } finally {
    clearTimeout(timer)
  }
}
